344	     * The ceiling applied to {@link #getMembershipLevel() membershipLevel}: one above the current
345	     * maximum membershipLevel among this owner's existing household members. Derived at response
346	     * time and not persisted; {@code null} means no household member exists and no cap applies.
347	     */
348	    public Integer getMembershipLevelCap() {
349	        return this.membershipLevelCap;
350	    }
351	
352	    public void setMembershipLevelCap(Integer membershipLevelCap) {
353	        this.membershipLevelCap = membershipLevelCap;
354	    }
355	
356	    /**
357	     * The owner's membership points, derived at response time. Starts at {@code 0}, plus 2 when an
358	     * email is present, plus 1 when {@link #namesakeCount} is 0, plus 2 when the
359	     * {@link #getHouseholdSize() household} has 3 or more members, plus 3 when tenure exceeds one
360	     * elapsed fiscal year (measured from the {@link #registrationDate}; see
361	     * {@link #getTenureFiscalYears()}).
362	     */
363	    public Integer getMembershipPoints() {
364	        int points = 0;
365	        if (this.email != null && !this.email.isEmpty()) {
366	            points += 2;
367	        }
368	        if (this.namesakeCount != null && this.namesakeCount == 0) {
369	            points += 1;
370	        }
371	        if (this.householdSize != null && this.householdSize >= 3) {
372	            points += 2;
373	        }
374	        if (getTenureFiscalYears() > 1) {
375	            points += 3;
376	        }
377	        return points;
378	    }
379	
380	    /**
381	     * The owner's numeric membership level, mapped from {@link #getMembershipPoints() membershipPoints}:
382	     * {@code 1} for 0-1 points, {@code 2} for 2-3 points, {@code 3} for 4-5 points, and {@code 4} for
383	     * 6 or more points.
384	     *
385	     * <p>When a {@link #getMembershipLevelCap() membershipLevelCap} is present the result is capped to
386	     * it, so a new owner's level cannot exceed one above the current maximum membershipLevel among
387	     * their household members. With no household member the cap is absent and the mapped level stands.
388	     */
389	    public Integer getMembershipLevel() {
390	        int points = getMembershipPoints();
391	        int level;
392	        if (points <= 1) {
393	            level = 1;
394	        }
395	        else if (points <= 3) {
396	            level = 2;
397	        }
398	        else if (points <= 5) {
399	            level = 3;
400	        }
401	        else {
402	            level = 4;
403	        }
404	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
405	            return this.membershipLevelCap;
406	        }
407	        return level;
408	    }
409	
410	    /**
411	     * The fiscal year containing {@code date}: fiscal years start on 1 July and are named for the
412	     * calendar year in which they end, so 1 July 2026 – 30 June 2027 is fiscal year {@code 2027}.
413	     */
414	    public static int fiscalYear(LocalDate date) {
415	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
416	    }
417	
418	    /**
419	     * The owner's fiscal year, derived at response time from the business-day-adjusted
420	     * {@link #registrationDate} (stamped business-day-adjusted at creation) as {@code FY<YY>},
421	     * where the fiscal year starts on 1 July and {@code YY} is the last two digits of the fiscal
422	     * year (the calendar year in which it ends). {@code null} when the registration date is absent.
423	     * Not persisted.
424	     */
425	    public String getFiscalYear() {
426	        if (this.registrationDate == null) {
427	            return null;
428	        }
429	        return String.format(Locale.ROOT, "FY%02d", fiscalYear(this.registrationDate) % 100);
430	    }
431	
432	    /**
433	     * The owner's tenure in elapsed fiscal years, measured from the {@link #registrationDate}'s
434	     * fiscal year to the current fiscal year (fiscal years start on 1 July); zero when the
435	     * registration date is absent or falls in a later fiscal year than today.
436	     */
437	    private long getTenureFiscalYears() {
438	        if (this.registrationDate == null) {
439	            return 0;
440	        }
441	        long years = (long) fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate);
442	        return Math.max(years, 0);
443	    }
444	
445	    /** Fixed city-to-region table used to derive {@link #getLocality()}. */
446	    private static final Map<String, String> CITY_REGION = Map.of(
447	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
448	
449	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
450	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
451	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
452	
453	    /** Fixed region-to-IANA-timezone table used to derive {@link #getTimezone()}. */
454	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
455	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
456	
457	    /**
458	     * The fixed city-to-region mapping ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
459	     * {@code Brisbane -> QLD}): the region for {@code city}, or {@code null} when the city is not in
460	     * the table. Used only by postcode validation, which branches on "known region or not" by testing
461	     * for {@code null} before range-checking the postcode.
462	     */
463	    public static String regionOf(String city) {
464	        return CITY_REGION.get(city);
465	    }
466	
467	    /**
468	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
469	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
470	     * absent, not a 4-digit number, or in no known range.
471	     */
472	    public static String regionOfPostcode(String postcode) {
473	        if (postcode == null || postcode.isEmpty()) {
474	            return null;
475	        }
476	        int value;
477	        try {
478	            value = Integer.parseInt(postcode);
479	        } catch (NumberFormatException ex) {
480	            return null;
481	        }
482	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
483	            int[] range = entry.getValue();
484	            if (value >= range[0] && value <= range[1]) {
485	                return entry.getKey();
486	            }
487	        }
488	        return null;
489	    }
490	
491	    /**
492	     * The owner's region, derived at response time from the {@code REGION} prefix of the
493	     * {@link #customerCode} (the segment before the first {@code '-'}). Because the customer code is
494	     * assigned as {@code <REGION>-<HASH8>} with REGION taken from the postcode, the locality follows
495	     * the same region-and-hash identity as the customer code. {@code UNKNOWN} when the owner has no
496	     * customer code.
497	     */
498	    public String getLocality() {
499	        if (this.customerCode == null) {
500	            return "UNKNOWN";
501	        }
502	        int dash = this.customerCode.indexOf('-');
503	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
504	    }
505	
506	    /**
507	     * The owner's IANA timezone name, derived at response time from the {@link #getLocality()
508	     * locality}/region via the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
509	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null}
510	     * when the region is not in the table. Not persisted.
511	     */
512	    public String getTimezone() {
513	        return REGION_TIMEZONE.get(getLocality());
514	    }
515	
516	    /**
517	     * The owner's preferred contact channel, derived at response time: {@code EMAIL} when an
518	     * email is present, otherwise {@code PHONE}. Not persisted.
519	     */
520	    public String getContactPreference() {
521	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
522	    }
523	
524	    /**
525	     * A single Luhn check digit (0-9) derived at response time over the digits contained in
526	     * {@link #customerCode} (non-digit characters are ignored), or {@code null} when the owner
527	     * has no customer code. Computed with the standard Luhn algorithm — doubling every second
528	     * digit from the right, subtracting 9 from any result over 9, and taking
529	     * {@code (10 - sum % 10) % 10}. Not persisted.
530	     */
531	    public Integer getCheckDigit() {
532	        if (this.customerCode == null) {
533	            return null;
534	        }
535	        int sum = 0;
536	        boolean dbl = true;
537	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
538	            char c = this.customerCode.charAt(i);
539	            if (c < '0' || c > '9') {
540	                continue;
541	            }
542	            int d = c - '0';
543	            if (dbl) {
544	                d *= 2;
545	                if (d > 9) {
546	                    d -= 9;
547	                }
548	            }
549	            sum += d;
550	            dbl = !dbl;
551	        }
552	        return (10 - (sum % 10)) % 10;
553	    }
554	
555	    /**
556	     * The owner's deterministic identity key: the full lower-case hex SHA-256 of
557	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone is
558	     * stored in canonical E.164 form and the email lower-cased; an absent telephone or email
559	     * contributes an empty segment, and the last name is reduced to its {@link #soundex(String)
560	     * Soundex} code. Two owners share an identity exactly when this 64-character hex value is equal.
561	     *
562	     * <p>This is the single key duplicate detection keys off: a create is rejected 409 when a
563	     * non-deleted owner already carries the same identity key (see {@code DetectOwnerDuplicate}).
564	     * Because the telephone participates in the key, two owners with the same last name and postcode
565	     * but different telephones no longer collide here — they are flagged as a soft match instead (see
566	     * {@code DetectOwnerPossibleDuplicate}). Derived at response time and not persisted.
567	     */
568	    public String getIdentityKey() {
569	        String telephone = keyPart(this.telephone);
570	        String email = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
571	        String input = telephone + "|" + email + "|" + soundex(this.lastName);
572	        return sha256Hex(input);
573	    }
574	
575	    private static String keyPart(String value) {
576	        return value == null ? "" : value;
577	    }
578	
579	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
580	    private static String sha256Hex(String value) {
581	        try {
582	            byte[] digest = MessageDigest.getInstance("SHA-256")
583	                    .digest(value.getBytes(StandardCharsets.UTF_8));
584	            StringBuilder sb = new StringBuilder(digest.length * 2);
585	            for (byte b : digest) {
586	                sb.append(String.format("%02x", b));
587	            }
588	            return sb.toString();
589	        }
590	        catch (NoSuchAlgorithmException ex) {
591	            throw new IllegalStateException("SHA-256 not available", ex);
592	        }
593	    }
594	
595	    /**
596	     * The American Soundex code for {@code name}: the retained first letter followed by up to three
597	     * digits mapping the remaining consonants (b/f/p/v→1, c/g/j/k/q/s/x/z→2, d/t→3, l→4, m/n→5, r→6),
598	     * right-padded with zeros to length four. Adjacent duplicate codes collapse; {@code h}/{@code w}
599	     * do not separate repeated codes while vowels (and {@code y}) do. Non-letters are ignored. Returns
600	     * {@code ""} when {@code name} is null or has no letters. Two last names that sound alike share a
601	     * code, which is how the identity key and soft-match group surnames phonetically.
602	     */
603	    public static String soundex(String name) {
604	        if (name == null) {
605	            return "";
606	        }
607	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
608	        if (letters.isEmpty()) {
609	            return "";
610	        }
611	        StringBuilder code = new StringBuilder();
612	        code.append(letters.charAt(0));
613	        char prev = soundexDigit(letters.charAt(0));
614	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
615	            char c = letters.charAt(i);
616	            if (c == 'H' || c == 'W') {
617	                continue; // ignored and does not separate repeated codes
618	            }
619	            char digit = soundexDigit(c);
620	            if (digit != '0' && digit != prev) {
621	                code.append(digit);
622	            }
623	            prev = digit; // a vowel resets prev so a later same code is emitted again
624	        }
625	        while (code.length() < 4) {
626	            code.append('0');
627	        }
628	        return code.toString();
629	    }
630	
631	    /** The Soundex digit for an upper-case letter, {@code '0'} for vowels and {@code h}/{@code w}. */
632	    private static char soundexDigit(char c) {
633	        switch (c) {
634	            case 'B': case 'F': case 'P': case 'V':
635	                return '1';
636	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
637	                return '2';
638	            case 'D': case 'T':
639	                return '3';
640	            case 'L':
641	                return '4';
642	            case 'M': case 'N':
643	                return '5';
644	            case 'R':
645	                return '6';
646	            default:
647	                return '0';
648	        }
649	    }
650	
651	    /**
652	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
653	     * national digits (everything after the country code) grouped in threes and space-separated —
654	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
655	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
656	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
657	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
658	     */
659	    public String getTelephoneDisplay() {
660	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
661	            return null;
662	        }
663	        String digits = this.telephone.substring(1);
664	        int countryCodeLength;
665	        if (digits.startsWith("61")) {
666	            countryCodeLength = 2;
667	        }
668	        else if (digits.startsWith("1")) {
669	            countryCodeLength = 1;
670	        }
671	        else {
672	            countryCodeLength = 2;
673	        }
674	        String countryCode = digits.substring(0, countryCodeLength);
675	        String national = digits.substring(countryCodeLength);
676	        StringBuilder display = new StringBuilder("+").append(countryCode);
677	        for (int i = 0; i < national.length(); i += 3) {
678	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
679	        }
680	        return display.toString();
681	    }
682	
683	    protected Set<Pet> getPetsInternal() {
684	        if (this.pets == null) {
685	            this.pets = new HashSet<>();
686	        }
687	        return this.pets;
688	    }
689	
690	    protected void setPetsInternal(Set<Pet> pets) {
691	        this.pets = pets;
692	    }
693	
694	    public List<Pet> getPets() {
695	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
696	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
697	        return Collections.unmodifiableList(sortedPets);
698	    }
699	
700	    public void setPets(List<Pet> pets) {
701	        this.pets = new HashSet<>(pets);
702	    }
703	
704	    public void addPet(Pet pet) {
705	        getPetsInternal().add(pet);
706	        pet.setOwner(this);
707	    }
708	
709	    /**
710	     * Return the Pet with the given name, or null if none found for this Owner.
711	     *
712	     * @param name to test
713	     * @return true if pet name is already in use
714	     */
715	    public Pet getPet(String name) {
716	        return getPet(name, false);
717	    }
718	
719	    /**
720	     * Return the Pet with the given name, or null if none found for this Owner.
721	     *
722	     * @param name to test
723	     * @return true if pet name is already in use
724	     */
725	    public Pet getPet(String name, boolean ignoreNew) {
726	        name = name.toLowerCase();
727	        for (Pet pet : getPetsInternal()) {
728	            if (!ignoreNew || !pet.isNew()) {
729	                String compName = pet.getName();
730	                compName = compName.toLowerCase();
731	                if (compName.equals(name)) {
732	                    return pet;
733	                }
734	            }
735	        }
736	        return null;
737	    }
738	
739	    public Pet getPet(Integer petId) {
740	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
741	    }
742	
743	    @Override
744	    public String toString() {
745	        return new ToStringCreator(this)
746	
747	            .append("id", this.getId())
748	            .append("new", this.isNew())
749	            .append("lastName", this.getLastName())
750	            .append("firstName", this.getFirstName())
751	            .append("address", this.address)
752	            .append("city", this.city)
753	            .append("telephone", this.telephone)
754	            .append("email", this.email)
755	            .toString();
756	    }
757	}
